    "os"
    "path/filepath"
    "regexp"
    "sort"
    "strconv"
    "strings"
    "unicode"
)

const banner = `
 _ __ _____   _(_)__  _____
| '__/ _ \ \ / / \ \ / / _ \
| | |  __/\ V /| |\ V /  __/
|_|  \___| \_/ |_| \_/ \___|

