var ruleCategories = map[string]string{
    "blank-imports": "imports", "context-as-argument": "context", "context-keys-type": "context",
    "dot-imports": "imports", "empty-block": "style", "error-naming": "errors",
    "error-return": "errors", "error-strings": "errors", "exported": "comments",
    "increment-decrement": "style", "indent-error-flow": "style", "package-comments": "comments",
    "range": "style", "receiver-naming": "naming", "redefines-builtin-id": "naming",
    "unexported-return": "style", "unreachable-code": "style", "unused-parameter": "unused",
    "var-declaration": "style", "var-naming": "naming",
}

var ruleConfidence = map[string]float64{
    "var-naming": 0.9,
}

type excludesFlag []string

func (e *excludesFlag) String() string { return strings.Join(*e, ",") }
func (e *excludesFlag) Set(v string) error { *e = append(*e, v); return nil }

type Config struct {
    Loaded      bool
    Severity    string
    Confidence  float64
    ErrorCode   int
    WarningCode int
    Rules       map[string]RuleConfig
}

type RuleConfig struct {
    Disabled bool
    Severity string
    Args     []string
}

type PositionPoint struct {
    Filename string
    Offset   int
    Line     int
    Column   int
}

type FailurePosition struct {
    Start PositionPoint
    End   PositionPoint
}

type Failure struct {
    Severity        string
    Failure         string
    RuleName        string
    Category        string
    Position        FailurePosition
    Confidence      float64
    ReplacementLine string
}

type FileData struct {
    Path       string
    Display    string
    Src        []byte
    Fset       *token.FileSet
    File       *ast.File
    ParseError error
    Directives []Directive
}

type Directive struct {
    Line   int
    Kind   string
    Rules  map[string]bool
    All    bool
}

func main() {
    os.Exit(run())
}

func run() int {
    var configPath string
    var formatter string
    var maxOpen int
    var setExit bool
    var excl excludesFlag
    var showVersion bool

    fs := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    fs.StringVar(&configPath, "config", "", "path to the configuration TOML file, defaults to $XDG_CONFIG_HOME/revive.toml or $HOME/revive.toml, if present (i.e. -config myconf.toml)")
    fs.Var(&excl, "exclude", "list of globs which specify files to be excluded (i.e. -exclude foo/...)")
    fs.StringVar(&formatter, "formatter", "", "formatter to be used for the output (i.e. -formatter stylish)")
    fs.IntVar(&maxOpen, "max_open_files", 0, "maximum number of open files at the same time")
    fs.BoolVar(&setExit, "set_exit_status", false, "set exit status to 1 if any issues are found, overwrites errorCode and warningCode in config")
    fs.BoolVar(&showVersion, "version", false, "get revive version")
    _ = maxOpen
    fs.Usage = func() {
        fmt.Fprint(os.Stdout, banner)
        fmt.Fprintf(os.Stderr, "Usage of %s:\n", os.Args[0])
        fs.PrintDefaults()
    }
    if err := fs.Parse(os.Args[1:]); err != nil {
        return 2
    }
    if showVersion {
        fmt.Print(versionText)
        return 0
    }
    if formatter == "" {
        formatter = "default"
    }
    if !knownFormatter(formatter) {
        fmt.Fprintf(os.Stderr, "formatting - getting formatter: unknown formatter %s\n", formatter)
        return 1
    }

    cfg, err := loadConfig(configPath)
    if err != nil {
        fmt.Fprintln(os.Stderr, err.Error())
        return 1
    }
    args := fs.Args()
    if len(args) == 0 {
        return 0
    }
    files, err := collectFiles(args, []string(excl))
    if err != nil {
        fmt.Fprintln(os.Stderr, err.Error())
        return 1
    }
    failures := lint(files, cfg)
    filtered := failures[:0]
    for _, f := range failures {
        if cfg.Confidence > 0 && f.Confidence < cfg.Confidence {
            continue
        }
        filtered = append(filtered, f)
    }
    failures = filtered
    format(formatter, failures)

    if len(failures) == 0 {
        return 0
    }
    if setExit {
        return 1
    }
    if cfg.Loaded {
        hasError := false
        hasWarn := false
        for _, f := range failures {
            if f.Severity == "error" { hasError = true } else { hasWarn = true }
        }
        if hasError && cfg.ErrorCode != 0 { return cfg.ErrorCode }
        if hasWarn && cfg.WarningCode != 0 { return cfg.WarningCode }
    }
    return 0
}

func knownFormatter(s string) bool {
    switch s { case "default", "json", "ndjson", "friendly", "stylish", "checkstyle", "sarif", "plain", "unix": return true }
    return false
}

func loadConfig(path string) (Config, error) {
    cfg := Config{Severity: "warning", ErrorCode: 0, WarningCode: 0, Rules: map[string]RuleConfig{}}
    if path == "" {
        candidates := []string{}
        if x := os.Getenv("XDG_CONFIG_HOME"); x != "" { candidates = append(candidates, filepath.Join(x, "revive.toml")) }
        if h := os.Getenv("HOME"); h != "" { candidates = append(candidates, filepath.Join(h, "revive.toml")) }
        for _, c := range candidates {
            if _, err := os.Stat(c); err == nil { path = c; break }
        }
        if path == "" {
            for _, r := range defaultRules { cfg.Rules[r] = RuleConfig{} }
            return cfg, nil
        }
    }
    b, err := os.ReadFile(path)
    if err != nil { return cfg, errors.New("cannot read the config file") }
    cfg.Loaded = true
    if err := parseSimpleTOML(string(b), &cfg); err != nil { return cfg, fmt.Errorf("cannot parse the config file: %v", err) }
    return cfg, nil
}

func parseSimpleTOML(s string, cfg *Config) error {
    current := ""
    for idx, raw := range strings.Split(s, "\n") {
        line := stripComment(raw)
        line = strings.TrimSpace(line)
        if line == "" { continue }
        if strings.HasPrefix(line, "[") {
            if !strings.HasSuffix(line, "]") { return fmt.Errorf("toml: line %d: expected '.' or ']' to end table name, but got %q instead", idx+1, line) }
            name := strings.TrimSpace(line[1:len(line)-1])
            if strings.HasPrefix(name, "rule.") {
                current = strings.Trim(strings.TrimPrefix(name, "rule."), "\"")
                if _, ok := cfg.Rules[current]; !ok { cfg.Rules[current] = RuleConfig{} }
            } else { current = "" }
            continue
        }
        parts := strings.SplitN(line, "=", 2)
        if len(parts) != 2 { return fmt.Errorf("toml: line %d: expected key/value", idx+1) }
        key := strings.TrimSpace(parts[0])
        val := strings.TrimSpace(parts[1])
        if val == "[" || strings.HasSuffix(val, "[") { return errors.New("toml: line 1 (last key \"not\"): unexpected EOF; expected value") }
        if current == "" {
            switch key {
            case "severity": cfg.Severity = parseString(val)
            case "confidence": if f, err := strconv.ParseFloat(strings.Trim(val, "\""), 64); err == nil { cfg.Confidence = f }
            case "errorCode": if i, err := strconv.Atoi(strings.Trim(val, "\"")); err == nil { cfg.ErrorCode = i }
            case "warningCode": if i, err := strconv.Atoi(strings.Trim(val, "\"")); err == nil { cfg.WarningCode = i }
            }
        } else {
            rc := cfg.Rules[current]
            switch key {
            case "Disabled", "disabled": rc.Disabled = strings.EqualFold(strings.Trim(val, "\""), "true")
            case "severity": rc.Severity = parseString(val)
            case "arguments": rc.Args = parseArray(val)
            }
            cfg.Rules[current] = rc
        }
    }
    return nil
}

func stripComment(s string) string {
    in := false
    for i, r := range s {
        if r == '"' { in = !in }
        if r == '#' && !in { return s[:i] }
    }
    return s
}
func parseString(v string) string { return strings.Trim(strings.TrimSpace(v), "\"") }
func parseArray(v string) []string {
    v = strings.TrimSpace(v); v = strings.TrimPrefix(v, "["); v = strings.TrimSuffix(v, "]")
    if strings.TrimSpace(v)=="" { return nil }
    var out []string
    for _, p := range strings.Split(v, ",") { out = append(out, parseString(p)) }
    return out
}

func collectFiles(args []string, excludes []string) ([]*FileData, error) {
    cwd, _ := os.Getwd()
    seen := map[string]bool{}
    var paths []struct{ path, display string }
    add := func(path, display string) {
        abs, _ := filepath.Abs(path)
        if seen[abs] { return }
        seen[abs] = true
        display = filepath.ToSlash(display)
        if isExcluded(display, excludes) { return }
        paths = append(paths, struct{path, display string}{path, display})
    }
    for _, arg := range args {
        if strings.HasSuffix(arg, "/...") || arg == "./..." || arg == "..." {
            base := strings.TrimSuffix(arg, "/...")
            if base == "..." || base == "" { base = "." }
            if strings.HasPrefix(base, "./") { base = strings.TrimPrefix(base, "./") }
            if base == "" { base = "." }
            if st, err := os.Stat(base); err != nil || !st.IsDir() {
                return nil, fmt.Errorf("linting - getting packages: getting packages - resolving packages in dots: cannot find package %q in:\n\t%s", arg, strings.TrimPrefix(base, "./"))
            }
            filepath.WalkDir(base, func(path string, d fs.DirEntry, err error) error {
                if err != nil || !d.IsDir() { return nil }
                entries, _ := os.ReadDir(path)
                hasGo := false
                for _, e := range entries { if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") { hasGo = true; break } }
                if hasGo {
                    for _, e := range entries {
                        if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") {
                            p := filepath.Join(path, e.Name())
                            rel, _ := filepath.Rel(cwd, p); if rel == "." { rel = e.Name() }
                            add(p, rel)
                        }
                    }
                }
                return nil
            })
            continue
        }
        if strings.HasSuffix(arg, ".go") {
            if _, err := os.Stat(arg); err != nil { return nil, fmt.Errorf("cannot read file %s", arg) }
            add(arg, arg)
            continue
        }
        st, err := os.Stat(arg)
        if err != nil || !st.IsDir() {
            clean := strings.TrimPrefix(arg, "./")
            return nil, fmt.Errorf("linting - getting packages: getting packages - resolving packages in dots: cannot find package %q in:\n\t%s", arg, clean)
        }
        entries, _ := os.ReadDir(arg)
        for _, e := range entries {
            if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") {
                p := filepath.Join(arg, e.Name())
                rel, _ := filepath.Rel(cwd, p)
                add(p, rel)
            }
        }
    }
    sort.Slice(paths, func(i,j int) bool { return paths[i].display < paths[j].display })
    var out []*FileData
    for _, p := range paths {
        src, _ := os.ReadFile(p.path)
        fset := token.NewFileSet()
        file, err := parser.ParseFile(fset, p.display, src, parser.ParseComments)
        fd := &FileData{Path:p.path, Display:p.display, Src:src, Fset:fset, File:file, ParseError:err}
        if file != nil { fd.Directives = parseDirectives(file, fset) }
        out = append(out, fd)
    }
    return out, nil
}

func isExcluded(display string, excludes []string) bool {
    for _, ex := range excludes {
        if ex == display { return true }
        if strings.HasSuffix(ex, "/...") {
            pref := strings.TrimSuffix(ex, "/...")
            pref = strings.TrimPrefix(pref, "./")
            d := strings.TrimPrefix(display, "./")
            if d == pref || strings.HasPrefix(d, pref+"/") { return true }
        }
        if strings.ContainsAny(ex, "*?[ ") {
            if ok, _ := filepath.Match(ex, display); ok { return true }
        }
    }
    return false
}

func parseDirectives(f *ast.File, fset *token.FileSet) []Directive {
    var ds []Directive
    for _, cg := range f.Comments {
        for _, c := range cg.List {
            txt := strings.TrimSpace(strings.TrimPrefix(strings.TrimPrefix(c.Text, "//"), "/*"))
            txt = strings.TrimSuffix(txt, "*/")
            if !strings.HasPrefix(txt, "revive:") { continue }
            pos := fset.Position(c.Slash)
            body := strings.TrimPrefix(txt, "revive:")
            parts := strings.Split(body, ":")
            kind := parts[0]
            if kind != "disable" && kind != "enable" && kind != "disable-next-line" && kind != "disable-line" { continue }
            d := Directive{Line:pos.Line, Kind:kind, Rules:map[string]bool{}, All:true}
            if len(parts) > 1 && strings.TrimSpace(parts[1]) != "" {
                d.All = false
                for _, r := range strings.Split(parts[1], ",") { d.Rules[strings.TrimSpace(r)] = true }
            }
            ds = append(ds, d)
        }
    }
    sort.Slice(ds, func(i,j int) bool { return ds[i].Line < ds[j].Line })
    return ds
}

func lint(files []*FileData, cfg Config) []Failure {
    var failures []Failure
    active := func(rule string) bool { rc, ok := cfg.Rules[rule]; return ok && !rc.Disabled }
    add := func(fd *FileData, rule string, msg string, start, end token.Pos) {
        if !active(rule) { return }
        if fd == nil || fd.File == nil { return }
        sp := fd.Fset.Position(start)
        if fd.suppressed(rule, sp.Line) { return }
        ep := fd.Fset.Position(end)
        sev := cfg.Severity; if sev == "" { sev = "warning" }
        if rc := cfg.Rules[rule]; rc.Severity != "" { sev = rc.Severity }
        conf := 1.0; if c, ok := ruleConfidence[rule]; ok { conf = c }
        failures = append(failures, Failure{Severity:sev, Failure:msg, RuleName:rule, Category:ruleCategories[rule], Confidence:conf,
            Position: FailurePosition{Start: point(fd.Display, sp), End: point(fd.Display, ep)}, ReplacementLine:""})
    }
    // Parse errors are rendered as default-style failures.
    for _, fd := range files {
        if fd.ParseError != nil && fd.File == nil {
            tf := fd.Fset.File(token.Pos(1))
            _ = tf
            // parser errors include position; parse a leading file:line:col if possible.
            msg := fd.ParseError.Error()
            line, col := 1, 1
            re := regexp.MustCompile(`:(\d+):(\d+):`)
            if m := re.FindStringSubmatch(msg); m != nil { line,_ = strconv.Atoi(m[1]); col,_ = strconv.Atoi(m[2]) }
            failures = append(failures, Failure{Severity:"warning", Failure:"invalid file "+fd.Display+": "+msg, Position: FailurePosition{Start:PositionPoint{Filename:fd.Display,Line:line,Column:col}, End:PositionPoint{Filename:fd.Display,Line:line,Column:col}}, Confidence:1})
        }
    }
    // Package comments (one failure per package directory when absent).
    if active("package-comments") {
        groups := map[string][]*FileData{}
        for _, fd := range files { if fd.File != nil && !isTest(fd.Display) { groups[filepath.Dir(fd.Path)] = append(groups[filepath.Dir(fd.Path)], fd) } }
        for _, g := range groups {
            sort.Slice(g, func(i,j int) bool { return g[i].Display < g[j].Display })
            ok := false
            for _, fd := range g { if validPackageComment(fd) { ok = true; break } }
            if !ok && len(g)>0 {
                fd := g[0]
                add(fd, "package-comments", "should have a package comment", fd.File.Package, fd.File.Name.End())
            }
        }
    }
    for _, fd := range files {
        if fd.File == nil || fd.ParseError != nil { continue }
        lintImports(fd, add)
        lintDecls(fd, add)
        lintBodies(fd, add)
    }
    sort.SliceStable(failures, func(i,j int) bool {
        a,b := failures[i], failures[j]
        if a.Position.Start.Filename != b.Position.Start.Filename { return a.Position.Start.Filename < b.Position.Start.Filename }
        if a.Position.Start.Line != b.Position.Start.Line { return a.Position.Start.Line < b.Position.Start.Line }
        if a.Position.Start.Column != b.Position.Start.Column { return a.Position.Start.Column < b.Position.Start.Column }
        order := map[string]int{"package-comments":0,"dot-imports":1,"blank-imports":2,"exported":3,"var-naming":4}
        return order[a.RuleName] < order[b.RuleName]
    })
    return failures
}

func point(filename string, p token.Position) PositionPoint { return PositionPoint{Filename:filename, Offset:p.Offset, Line:p.Line, Column:p.Column} }
func isTest(path string) bool { return strings.HasSuffix(path, "_test.go") }

func (fd *FileData) suppressed(rule string, line int) bool {
    activeAll := false
    activeRules := map[string]bool{}
    for _, d := range fd.Directives {
        if d.Kind == "disable-next-line" && d.Line+1 == line && (d.All || d.Rules[rule]) { return true }
        if d.Kind == "disable-line" && d.Line == line && (d.All || d.Rules[rule]) { return true }
        if d.Line >= line { continue }
        switch d.Kind {
        case "disable":
            if d.All { activeAll = true } else { for r := range d.Rules { activeRules[r]=true } }
        case "enable":
            if d.All { activeAll = false; activeRules = map[string]bool{} } else { for r := range d.Rules { delete(activeRules,r) } }
        }
    }
    return activeAll || activeRules[rule]
}

func validPackageComment(fd *FileData) bool {
    if fd.File == nil || fd.File.Doc == nil { return false }
    txt := strings.TrimSpace(fd.File.Doc.Text())
    name := fd.File.Name.Name
    return strings.HasPrefix(txt, "Package "+name+" ") || strings.HasPrefix(txt, "Package "+name+".") || strings.HasPrefix(txt, "Command "+name+" ") || strings.HasPrefix(txt, "Command "+name+".")
}

func lintImports(fd *FileData, add func(*FileData,string,string,token.Pos,token.Pos)) {
    pkg := fd.File.Name.Name
    for _, im := range fd.File.Imports {
        if im.Name != nil && im.Name.Name == "." {
            add(fd, "dot-imports", "should not use dot imports", im.Name.Pos(), im.Name.End())
        }
        if im.Name != nil && im.Name.Name == "_" && pkg != "main" && !isTest(fd.Display) {
            justified := false
            if im.Doc != nil && strings.TrimSpace(im.Doc.Text()) != "" { justified = true }
            if im.Comment != nil && strings.TrimSpace(im.Comment.Text()) != "" { justified = true }
            if !justified { add(fd, "blank-imports", "a blank import should be only in a main or test package, or have a comment justifying it", im.Name.Pos(), im.Name.End()) }
        }
    }
}

func lintDecls(fd *FileData, add func(*FileData,string,string,token.Pos,token.Pos)) {
    pkg := fd.File.Name.Name
    for _, d := range fd.File.Decls {
        switch decl := d.(type) {
        case *ast.GenDecl:
            for _, spec := range decl.Specs {
                switch s := spec.(type) {
                case *ast.ValueSpec:
                    kind := strings.ToLower(decl.Tok.String())
                    for i, name := range s.Names {
                        if name.Name == "_" { continue }
                        if !isTest(fd.Display) && pkg != "main" && isExported(name.Name) {
                            if !hasUsefulDoc(name.Name, s.Doc, decl.Doc, kind) {
                                msg := fmt.Sprintf("exported %s %s should have comment or be unexported", kind, name.Name)
                                if kind == "const" && len(decl.Specs)>1 && decl.Doc==nil { msg = fmt.Sprintf("exported const %s should have comment (or a comment on this block) or be unexported", name.Name) }
                                add(fd, "exported", msg, name.Pos(), s.End())
                            } else if (kind=="const" || kind=="var") && s.Doc != nil && !commentStarts(s.Doc.Text(), name.Name, false) && decl.Doc==nil {
                                // revive is permissive for variables/constants; no warning.
                            }
                        }
                        if sug := lintName(name.Name); sug != name.Name {
                            msg := namingMessage(kind, name.Name, sug)
                            add(fd, "var-naming", msg, name.Pos(), name.End())
                        }
                        if kind == "var" { lintErrorNaming(fd, name, s, add); lintVarDeclaration(fd, name, s, i, add) }
                    }
                case *ast.TypeSpec:
                    name := s.Name
                    if !isTest(fd.Display) && pkg != "main" && isExported(name.Name) {
                        if !hasTypeDoc(name.Name, s.Doc, decl.Doc) {
                            msg := fmt.Sprintf("exported type %s should have comment or be unexported", name.Name)
                            start := name.Pos()
                            if decl.Doc != nil { msg = fmt.Sprintf("comment on exported type %s should be of the form \"%s ...\" (with optional leading article)", name.Name, name.Name); start = decl.Pos() }
                            add(fd, "exported", msg, start, s.End())
                        } else if (s.Doc != nil || decl.Doc != nil) && !typeCommentOK(name.Name, docText(s.Doc, decl.Doc)) {
                            start := name.Pos(); if decl.Doc != nil { start = decl.Pos() }
                            add(fd, "exported", fmt.Sprintf("comment on exported type %s should be of the form \"%s ...\" (with optional leading article)", name.Name, name.Name), start, s.End())
                        }
                    }
                    if sug := lintName(name.Name); sug != name.Name { add(fd, "var-naming", namingMessage("type", name.Name, sug), name.Pos(), name.End()) }
                }
            }
        case *ast.FuncDecl:
            name := decl.Name
            if !isTest(fd.Display) && pkg != "main" && isExported(name.Name) {
                if decl.Doc == nil || strings.TrimSpace(decl.Doc.Text()) == "" {
                    if decl.Recv != nil { add(fd, "exported", fmt.Sprintf("exported method %s.%s should have comment or be unexported", recvTypeName(decl.Recv), name.Name), decl.Pos(), decl.End())
                    } else { add(fd, "exported", fmt.Sprintf("exported function %s should have comment or be unexported", name.Name), decl.Pos(), decl.End()) }
                } else if !commentStarts(decl.Doc.Text(), name.Name, false) {
                    add(fd, "exported", fmt.Sprintf("comment on exported function %s should be of the form \"%s ...\"", name.Name, name.Name), decl.Pos(), decl.End())
                }
            }
            if sug := lintName(name.Name); sug != name.Name { add(fd, "var-naming", namingMessage("func", name.Name, sug), name.Pos(), name.End()) }
            lintFuncSignature(fd, decl, add)
        }
    }
}

func docText(a,b *ast.CommentGroup) string { if a!=nil { return a.Text() }; if b!=nil { return b.Text() }; return "" }
func hasUsefulDoc(name string, specDoc, declDoc *ast.CommentGroup, kind string) bool {
    if specDoc != nil && strings.TrimSpace(specDoc.Text()) != "" { return true }
    if declDoc != nil && strings.TrimSpace(declDoc.Text()) != "" { return true }
    return false
}
func hasTypeDoc(name string, specDoc, declDoc *ast.CommentGroup) bool { return (specDoc != nil && strings.TrimSpace(specDoc.Text())!="") || (declDoc!=nil && strings.TrimSpace(declDoc.Text())!="") }
func commentStarts(txt, name string, article bool) bool {
    txt = strings.TrimSpace(txt)
    return strings.HasPrefix(txt, name+" ") || strings.HasPrefix(txt, name+".")
}
func typeCommentOK(name, txt string) bool {
    txt = strings.TrimSpace(txt)
    if commentStarts(txt, name, false) { return true }
    for _, a := range []string{"A ", "An ", "The "} { if strings.HasPrefix(txt, a+name+" ") || strings.HasPrefix(txt, a+name+".") { return true } }
    return false
}

func lintErrorNaming(fd *FileData, name *ast.Ident, s *ast.ValueSpec, add func(*FileData,string,string,token.Pos,token.Pos)) {
    if isExported(name.Name) || strings.HasPrefix(name.Name, "err") { return }
    isErr := false
    if s.Type != nil && exprString(s.Type) == "error" { isErr = true }
    for _, v := range s.Values { if isErrorsNew(v) { isErr = true } }
    if isErr { add(fd, "error-naming", fmt.Sprintf("error var %s should have name of the form errFoo", name.Name), name.Pos(), name.End()) }
}
func lintVarDeclaration(fd *FileData, name *ast.Ident, s *ast.ValueSpec, idx int, add func(*FileData,string,string,token.Pos,token.Pos)) {
    if s.Type == nil || idx >= len(s.Values) { return }
    typ := exprString(s.Type); val := s.Values[idx]
    if typ == "string" {
        if bl, ok := val.(*ast.BasicLit); ok && bl.Kind == token.STRING {
            add(fd, "var-declaration", fmt.Sprintf("should omit type string from declaration of var %s; it will be inferred from the right-hand side", name.Name), s.Type.Pos(), s.Type.End())
        }
    }
    if isZeroValue(typ, val) {
        add(fd, "var-declaration", fmt.Sprintf("should drop = %s from declaration of var %s; it is the zero value", exprString(val), name.Name), val.Pos(), val.End())
    }
}
func isZeroValue(typ string, e ast.Expr) bool {
    switch typ {
    case "int", "int8", "int16", "int32", "int64", "uint", "uint8", "uint16", "uint32", "uint64", "uintptr", "float32", "float64": return exprString(e)=="0"
    case "bool": return exprString(e)=="false"
    case "string": if bl, ok := e.(*ast.BasicLit); ok && bl.Kind==token.STRING { return bl.Value=="\"\"" }
    }
    return false
}

func lintFuncSignature(fd *FileData, decl *ast.FuncDecl, add func(*FileData,string,string,token.Pos,token.Pos)) {
    // receiver-naming
    if decl.Recv != nil && len(decl.Recv.List)>0 && len(decl.Recv.List[0].Names)>0 {
        rn := decl.Recv.List[0].Names[0]
        if rn.Name == "this" || rn.Name == "self" { add(fd, "receiver-naming", "receiver name should be a reflection of its identity; don't use generic names such as \"this\" or \"self\"", decl.Pos(), decl.End()) }
    }
    // context-as-argument and parameter naming
    if decl.Type.Params != nil {
        paramIndex := 0
        for _, field := range decl.Type.Params.List {
            isCtx := exprString(field.Type) == "context.Context"
            for _, n := range field.Names {
                if n.Name != "_" {
                    if sug := lintName(n.Name); sug != n.Name { add(fd, "var-naming", fmt.Sprintf("don't use underscores in Go names; func parameter %s should be %s", n.Name, sug), n.Pos(), n.End()) }
                    if isCtx && paramIndex != 0 { add(fd, "context-as-argument", "context.Context should be the first parameter of a function", n.Pos(), n.End()) }
                }
                paramIndex++
            }
            if len(field.Names)==0 { paramIndex++ }
        }
    }
    // error-return and unexported-return
    if decl.Type.Results != nil && len(decl.Type.Results.List)>0 {
        var resultTypes []ast.Expr
        for _, r := range decl.Type.Results.List {
            count := len(r.Names); if count==0 { count=1 }
            for i:=0;i<count;i++ { resultTypes = append(resultTypes, r.Type) }
        }
        for i, t := range resultTypes {
            if exprString(t)=="error" && len(resultTypes)>1 && i != len(resultTypes)-1 { add(fd, "error-return", "error should be the last type when returning multiple items", decl.Pos(), decl.End()); break }
        }
        if decl.Name != nil && isExported(decl.Name.Name) && fd.File.Name.Name != "main" {
            for _, t := range resultTypes {
                tn := baseTypeName(t)
                if tn != "" && !isExported(tn) && tn != "error" && !isBuiltinType(tn) {
                    what := "func "+decl.Name.Name; if decl.Recv!=nil { what = "method "+recvTypeName(decl.Recv)+"."+decl.Name.Name }
                    add(fd, "unexported-return", fmt.Sprintf("exported %s returns unexported type %s.%s, which can be annoying to use", what, fd.File.Name.Name, tn), t.Pos(), t.End())
                }
            }
        }
    }
}

func lintBodies(fd *FileData, add func(*FileData,string,string,token.Pos,token.Pos)) {
    ast.Inspect(fd.File, func(n ast.Node) bool {
        switch x := n.(type) {
        case *ast.FuncDecl:
            if x.Body != nil { lintUnusedParams(fd, x, add) }
        case *ast.AssignStmt:
            if (x.Tok == token.ADD_ASSIGN || x.Tok == token.SUB_ASSIGN) && len(x.Lhs)==1 && len(x.Rhs)==1 && exprString(x.Rhs[0])=="1" {
                op := "++"; tok := "+="; if x.Tok == token.SUB_ASSIGN { op="--"; tok="-=" }
                add(fd, "increment-decrement", fmt.Sprintf("should replace %s %s 1 with %s%s", exprString(x.Lhs[0]), tok, exprString(x.Lhs[0]), op), x.Pos(), x.End())
            }
            if x.Tok == token.DEFINE || x.Tok == token.ASSIGN {
                for _, lhs := range x.Lhs { if id, ok := lhs.(*ast.Ident); ok { lintBuiltInRedef(fd, id, add); if sug:=lintName(id.Name); sug!=id.Name { add(fd, "var-naming", namingMessage("var", id.Name, sug), id.Pos(), id.End()) } } }
            }
        case *ast.RangeStmt:
            if id, ok := x.Value.(*ast.Ident); ok && id.Name == "_" {
                add(fd, "range", "should omit 2nd value from range; this loop is equivalent to `for "+exprString(x.Key)+" := range ...`", id.Pos(), id.End())
            }
        case *ast.IfStmt:
            if x.Else != nil && len(x.Body.List)>0 && endsWithReturn(x.Body.List) {
                add(fd, "indent-error-flow", "if block ends with a return statement, so drop this else and outdent its block", x.Else.Pos(), x.Else.End())
            }
        case *ast.BlockStmt:
            // unreachable after return
            for i, st := range x.List { if _, ok := st.(*ast.ReturnStmt); ok && i < len(x.List)-1 { add(fd, "unreachable-code", "unreachable code after this statement", st.Pos(), st.End()) } }
        case *ast.ForStmt:
            if x.Body != nil && len(x.Body.List)==0 { add(fd, "empty-block", "this block is empty, you can remove it", x.Body.Lbrace, x.Body.Rbrace) }
        case *ast.IfStmt:
            // unreachable: covered above
        case *ast.CallExpr:
            lintCalls(fd, x, add)
        }
        return true
    })
    // empty if blocks need separate walk because duplicate case impossible above
    ast.Inspect(fd.File, func(n ast.Node) bool {
        switch x := n.(type) {
        case *ast.IfStmt:
            if x.Body != nil && len(x.Body.List)==0 { add(fd, "empty-block", "this block is empty, you can remove it", x.Body.Lbrace, x.Body.Rbrace) }
        case *ast.SwitchStmt:
            if x.Body != nil && len(x.Body.List)==0 { add(fd, "empty-block", "this block is empty, you can remove it", x.Body.Lbrace, x.Body.Rbrace) }
        }
        return true
    })
}

func lintCalls(fd *FileData, c *ast.CallExpr, add func(*FileData,string,string,token.Pos,token.Pos)) {
    sel := ""
    if s, ok := c.Fun.(*ast.SelectorExpr); ok { sel = exprString(s.X)+"."+s.Sel.Name }
    if (strings.HasSuffix(sel, ".New") || strings.HasSuffix(sel, ".Errorf")) && len(c.Args)>0 {
        if bl, ok := c.Args[0].(*ast.BasicLit); ok && bl.Kind == token.STRING {
            val, err := strconv.Unquote(bl.Value); if err==nil && badErrorString(val) { add(fd, "error-strings", "error strings should not be capitalized or end with punctuation or a newline", bl.Pos(), bl.End()) }
        }
    }
    if sel == "context.WithValue" && len(c.Args)>=2 {
        if bl, ok := c.Args[1].(*ast.BasicLit); ok && bl.Kind == token.STRING { add(fd, "context-keys-type", "should not use basic type untyped string as key in context.WithValue", bl.Pos(), bl.End()) }
    }
}
func badErrorString(s string) bool {
    if s == "" { return false }
    r := []rune(s)
    first := r[0]
    if unicode.IsUpper(first) { return true }
    last := r[len(r)-1]
    return last=='.' || last==':' || last=='!' || last=='?' || last=='\n'
}

func lintUnusedParams(fd *FileData, decl *ast.FuncDecl, add func(*FileData,string,string,token.Pos,token.Pos)) {
    if decl.Type.Params == nil || decl.Body == nil { return }
    params := map[string]*ast.Ident{}
    for _, f := range decl.Type.Params.List { for _, n := range f.Names { if n.Name != "_" { params[n.Name]=n } } }
    if len(params)==0 { return }
    used := map[string]int{}
    ast.Inspect(decl.Body, func(n ast.Node) bool { if id, ok := n.(*ast.Ident); ok { used[id.Name]++ }; return true })
    for name, id := range params { if used[name]==0 { add(fd, "unused-parameter", fmt.Sprintf("parameter '%s' seems to be unused, consider removing or renaming it as _", name), id.Pos(), id.End()) } }
}

var builtinFuncs = map[string]bool{"append":true,"cap":true,"close":true,"complex":true,"copy":true,"delete":true,"imag":true,"len":true,"make":true,"new":true,"panic":true,"print":true,"println":true,"real":true,"recover":true}
func lintBuiltInRedef(fd *FileData, id *ast.Ident, add func(*FileData,string,string,token.Pos,token.Pos)) { if builtinFuncs[id.Name] { add(fd, "redefines-builtin-id", fmt.Sprintf("redefinition of the built-in function %s", id.Name), id.Pos(), id.End()) } }

func endsWithReturn(stmts []ast.Stmt) bool { if len(stmts)==0 { return false }; switch stmts[len(stmts)-1].(type) { case *ast.ReturnStmt, *ast.BranchStmt: return true }; return false }

func isErrorsNew(e ast.Expr) bool { if c, ok := e.(*ast.CallExpr); ok { if s, ok := c.Fun.(*ast.SelectorExpr); ok { return exprString(s.X)=="errors" && s.Sel.Name=="New" } }; return false }
func isExported(s string) bool { if s=="" { return false }; r,_ := utf8DecodeRuneInString(s); return unicode.IsUpper(r) }
func utf8DecodeRuneInString(s string) (rune,int) { for _, r := range s { return r, len(string(r)) }; return 0,0 }

var commonInitialisms = map[string]bool{"API":true,"ASCII":true,"CPU":true,"CSS":true,"DNS":true,"EOF":true,"GUID":true,"HTML":true,"HTTP":true,"HTTPS":true,"ID":true,"IP":true,"JSON":true,"LHS":true,"QPS":true,"RAM":true,"RHS":true,"RPC":true,"SLA":true,"SMTP":true,"SQL":true,"SSH":true,"TCP":true,"TLS":true,"TTL":true,"UDP":true,"UI":true,"UID":true,"UUID":true,"URI":true,"URL":true,"UTF8":true,"VM":true,"XML":true,"XMPP":true,"XSRF":true,"XSS":true}

func lintName(name string) string {
    if name == "_" || name == "" { return name }
    if strings.Contains(name, "_") {
        parts := strings.Split(name, "_")
        out := ""
        for i, p := range parts {
            if p=="" { continue }
            up := strings.ToUpper(p)
            if commonInitialisms[up] { out += up; continue }
            if i==0 { out += p } else { out += strings.ToUpper(p[:1]) + strings.ToLower(p[1:]) }
        }
        return out
    }
    words := splitCamel(name)
    if len(words) <= 1 { return name }
    changed := false
    for i,w := range words {
        up := strings.ToUpper(w)
        if commonInitialisms[up] && w != up { words[i]=up; changed=true }
    }
    if changed { return strings.Join(words, "") }
    return name
}

func splitCamel(s string) []string {
    var words []string
    start := 0
    r := []rune(s)
    for i:=1; i<len(r); i++ {
        if unicode.IsUpper(r[i]) && (unicode.IsLower(r[i-1]) || (i+1<len(r) && unicode.IsLower(r[i+1]))) {
            words = append(words, string(r[start:i])); start=i
        }
    }
    words = append(words, string(r[start:]))
    return words
}

func namingMessage(kind, old, sug string) string {
    if strings.Contains(old, "_") { return fmt.Sprintf("don't use underscores in Go names; %s %s should be %s", kind, old, sug) }
    return fmt.Sprintf("%s %s should be %s", kind, old, sug)
}

func exprString(e ast.Expr) string {
    if e == nil { return "" }
    var b bytes.Buffer
    writeExpr(&b, e)
    return b.String()
}
func writeExpr(b *bytes.Buffer, e ast.Expr) {
    switch x := e.(type) {
    case *ast.Ident: b.WriteString(x.Name)
    case *ast.SelectorExpr: writeExpr(b, x.X); b.WriteByte('.'); b.WriteString(x.Sel.Name)
    case *ast.StarExpr: b.WriteByte('*'); writeExpr(b, x.X)
    case *ast.BasicLit: b.WriteString(x.Value)
    case *ast.ArrayType: b.WriteString("[]"); writeExpr(b, x.Elt)
    case *ast.MapType: b.WriteString("map["); writeExpr(b, x.Key); b.WriteByte(']'); writeExpr(b, x.Value)
    default: b.WriteString(fmt.Sprintf("%T", e))
    }
}
func baseTypeName(e ast.Expr) string { switch x:=e.(type) { case *ast.Ident: return x.Name; case *ast.StarExpr: return baseTypeName(x.X); case *ast.SelectorExpr: return ""; case *ast.ArrayType: return baseTypeName(x.Elt) }; return "" }
func isBuiltinType(s string) bool { switch s { case "bool","byte","complex64","complex128","error","float32","float64","int","int8","int16","int32","int64","rune","string","uint","uint8","uint16","uint32","uint64","uintptr": return true }; return false }
func recvTypeName(fl *ast.FieldList) string { if fl==nil || len(fl.List)==0 { return "" }; return strings.TrimPrefix(exprString(fl.List[0].Type), "*") }

func format(formatter string, fs []Failure) {
    switch formatter {
    case "default": formatDefault(fs, false)
    case "plain": formatDefault(fs, true)
    case "unix": for _, f := range fs { fmt.Printf("%s:%d:%d: [%s] %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.RuleName, f.Failure) }; if len(fs)>0 { fmt.Println() }
    case "json": b,_ := json.Marshal(fs); fmt.Print(string(b))
    case "ndjson": for _, f := range fs { b,_ := json.Marshal(f); fmt.Println(string(b)) }; if len(fs)>0 { fmt.Println() }
    case "checkstyle": formatCheckstyle(fs)
    case "friendly": formatFriendly(fs)
    case "stylish": formatStylish(fs)
    case "sarif": formatSARIF(fs)
    }
}
func formatDefault(fs []Failure, plain bool) { for _, f := range fs { if plain && f.RuleName!="" { fmt.Printf("%s:%d:%d: %s https://revive.run/r#%s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.Failure, f.RuleName) } else { fmt.Printf("%s:%d:%d: %s\n", f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column, f.Failure) } }; if plain && len(fs)>0 { fmt.Println() } }

func formatFriendly(fs []Failure) {
    warnCounts := map[string]int{}; errN:=0; warnN:=0
    for _, f := range fs { if f.Severity=="error" { errN++ } else { warnN++; warnCounts[f.RuleName]++ }; icon := "⚠"; if f.Severity=="error" { icon="✖" }; fmt.Printf("  %s  https://revive.run/r#%s  %s\n  %s:%d:%d\n\n", icon, f.RuleName, f.Failure, f.Position.Start.Filename, f.Position.Start.Line, f.Position.Start.Column) }
    if len(fs)>0 { fmt.Printf("⚠ %d problems (%d errors, %d warnings)\n\n", len(fs), errN, warnN); if warnN>0 { fmt.Println("Warnings:"); keys:=make([]string,0,len(warnCounts)); for k:=range warnCounts{keys=append(keys,k)}; sort.Strings(keys); for _,k:=range keys{fmt.Printf("  %d  %s\n", warnCounts[k], k)}; fmt.Println() } }
}
func formatStylish(fs []Failure) {
    by := map[string][]Failure{}; var files []string
    for _, f := range fs { if _,ok:=by[f.Position.Start.Filename]; !ok { files=append(files,f.Position.Start.Filename) }; by[f.Position.Start.Filename]=append(by[f.Position.Start.Filename],f) }
    sort.Strings(files)
    for _, file := range files { fmt.Println(file); for _, f := range by[file] { fmt.Printf("  (%d, %d)  %-36s %s\n", f.Position.Start.Line, f.Position.Start.Column, "https://revive.run/r#"+f.RuleName, f.Failure) }; fmt.Println() }
    if len(fs)>0 { errN:=0; for _,f:=range fs{ if f.Severity=="error"{errN++} }; fmt.Printf("\n ✖ %d problems (%d errors) (%d warnings)\n", len(fs), errN, len(fs)-errN) }
}

type checkstyle struct { XMLName xml.Name `xml:"checkstyle"`; Version string `xml:"version,attr"`; Files []csFile `xml:"file"` }
type csFile struct { Name string `xml:"name,attr"`; Errors []csError `xml:"error"` }
type csError struct { Line int `xml:"line,attr"`; Column int `xml:"column,attr"`; Message string `xml:"message,attr"`; Severity string `xml:"severity,attr"`; Source string `xml:"source,attr"` }
func formatCheckstyle(fs []Failure) {
    fmt.Println("<?xml version='1.0' encoding='UTF-8'?>")
    by:=map[string][]Failure{}; var files []string
    for _,f:=range fs{ if _,ok:=by[f.Position.Start.Filename]; !ok{files=append(files,f.Position.Start.Filename)}; by[f.Position.Start.Filename]=append(by[f.Position.Start.Filename],f)}; sort.Strings(files)
    fmt.Println("<checkstyle version=\"5.0\">")
    for _,file:=range files{ fmt.Printf("    <file name=\"%s\">\n", xmlEscape(file)); for _,f:=range by[file]{ conf:=strconv.FormatFloat(f.Confidence,'f',-1,64); fmt.Printf("      <error line=\"%d\" column=\"%d\" message=\"%s (confidence %s)\" severity=\"%s\" source=\"revive/%s\"/>\n", f.Position.Start.Line, f.Position.Start.Column, xmlEscape(f.Failure), conf, f.Severity, f.RuleName)}; fmt.Println("    </file>") }
    fmt.Println("</checkstyle>")
}
func xmlEscape(s string) string { var b bytes.Buffer; xml.EscapeText(&b, []byte(s)); return b.String() }

func formatSARIF(fs []Failure) {
    type loc struct { PhysicalLocation map[string]interface{} `json:"physicalLocation"` }
    type res struct { Level string `json:"level,omitempty"`; Locations []loc `json:"locations"`; Message map[string]string `json:"message"`; RuleID string `json:"ruleId"` }
    results := []res{}
    for _, f := range fs { level := ""; if f.Severity!="" { level=f.Severity }; results=append(results,res{Level:level, RuleID:f.RuleName, Message:map[string]string{"text":f.Failure}, Locations:[]loc{{PhysicalLocation:map[string]interface{}{"artifactLocation":map[string]string{"uri":f.Position.Start.Filename},"region":map[string]int{"startLine":f.Position.Start.Line,"startColumn":f.Position.Start.Column}}}}}) }
    rules:=[]map[string]interface{}{}
    seen:=map[string]bool{}
    for _,f:=range fs{ if !seen[f.RuleName] && f.RuleName!=""{seen[f.RuleName]=true; rules=append(rules,map[string]interface{}{"id":f.RuleName,"helpUri":"https://revive.run/r#"+f.RuleName,"properties":map[string]string{"severity":f.Severity}})} }
    out:=map[string]interface{}{"version":"2.1.0","runs":[]interface{}{map[string]interface{}{"results":results,"tool":map[string]interface{}{"driver":map[string]interface{}{"name":"revive","informationUri":"https://revive.run","rules":rules}}}}}
    b,_:=json.MarshalIndent(out,"","  "); fmt.Println(string(b))
}
